pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(value) = bytes.strip_prefix(r#"{"v":2,"type":"hello","value":""#)
        .and_then(|value| value.strip_suffix(r#""}"#))
    {
        return Ok(Msg::Hello(value.to_string()));
    }
    if let Some(sequence) = bytes
        .strip_prefix(r#"{"v":2,"type":"heartbeat","seq":"#)
        .and_then(|sequence| sequence.strip_suffix('}'))
        .and_then(|sequence| sequence.parse().ok())
    {
        return Ok(Msg::Heartbeat(sequence));
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(r#"{{"v":2,"type":"hello","value":"{}"}}"#, value),
        Msg::Heartbeat(sequence) => format!(r#"{{"v":2,"type":"heartbeat","seq":{}}}"#, sequence),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_ping_frame_successfully() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn heartbeat_roundtrips() {
        let message = Msg::Heartbeat(42);
        assert!(matches!(decode(&encode(&message)), Ok(Msg::Heartbeat(42))));
    }
}
